<h3 id="color-picker-props" tabindex="-1"><a class="header-anchor" href="#color-picker-props"><span><code v-pre>&lt;color-picker&gt;</code> Props</span></a></h3>
<table>
<thead>
<tr>
<th>参数名</th>
<th>描述</th>
<th>类型</th>
<th style="text-align:center">默认值</th>
</tr>
</thead>
<tbody>
<tr>
<td>model-value <strong>(v-model)</strong></td>
<td>绑定值</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>default-value</td>
<td>默认值（非受控状态）</td>
<td><code v-pre>string</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>format</td>
<td>颜色值的格式</td>
<td><code v-pre>'hex' | 'rgb'</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>size</td>
<td>尺寸</td>
<td><code v-pre>'xs' | 'sm' | 'md' | 'lg' | 'xl'</code></td>
<td style="text-align:center"><code v-pre>'md'</code></td>
</tr>
<tr>
<td>show-text</td>
<td>显示颜色值</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>show-history</td>
<td>显示历史颜色</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>show-preset</td>
<td>显示预设颜色</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>disabled</td>
<td>禁用</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>disabled-alpha</td>
<td>禁用透明通道</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>hide-trigger</td>
<td>没有触发元素，只显示颜色面板</td>
<td><code v-pre>boolean</code></td>
<td style="text-align:center"><code v-pre>false</code></td>
</tr>
<tr>
<td>trigger-props</td>
<td>接受所有 <a href="/vue/component/trigger">Trigger</a> 组件的Props</td>
<td><code v-pre>Partial&lt;TriggerProps&gt;</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>history-colors</td>
<td>历史颜色的颜色数组</td>
<td><code v-pre>string[]</code></td>
<td style="text-align:center"><code v-pre>-</code></td>
</tr>
<tr>
<td>preset-colors</td>
<td>预设颜色的颜色数组</td>
<td><code v-pre>string[]</code></td>
<td style="text-align:center"><code v-pre>() =&gt; colors</code></td>
</tr>
</tbody>
</table>
